package com.flashsale.coupon;import com.flashsale.common.api.ApiResponse;import com.flashsale.common.security.*;import com.flashsale.common.trace.TraceContext;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/coupons") class CouponClaimController {private final CouponClaimService s;private final JwtTokenService t;CouponClaimController(CouponClaimService s,JwtTokenService t){this.s=s;this.t=t;}@PostMapping("/{templateId}/claims")ApiResponse<Long> claim(@RequestHeader("Authorization")String h,@RequestHeader("Idempotency-Key")String k,@PathVariable long templateId){try{return ApiResponse.success(s.claim(t.parse(h.substring(7)),templateId,k),TraceContext.getOrCreate());}catch(StringIndexOutOfBoundsException e){throw new IllegalArgumentException("UNAUTHENTICATED");}}}
